function script:qs_goal_teach([string]$id) {
  switch -Exact ($id) {
    'notice' {
      q_say 'The notice says what happened and what to do. Get-Content it.'
    }
    'search' {
      q_say 'Select-String finds every line that contains a word, like a search box for files. Select-String "map-room" logs\* searches all 31 logs at once and shows which file and line each match came from. Look for a visit in the middle of the night.'
    }
    'who' {
      q_say 'The map room was opened at 02:51 on the 17th by badge 7714. Select-String 7714 staff.txt finds the one line with that badge. Then write the name into a new file with Set-Content.'
    }
    'count' {
      q_say 'A pipe, |, sends what one command makes into the next. Select-String 7714 logs\* finds every line; | Measure-Object counts them (the Count). Then Add-Content puts that number in your notes.'
    }
    'locker' {
      q_say 'Get-ChildItem -Recurse looks in every folder below, and -Filter keeps only matching names: Get-ChildItem lockers -Recurse -Filter "*otto*" finds Otto''s locker however deep it is.'
    }
    'map' {
      q_say 'A locker this ordinary is hiding something. Look closer: Get-ChildItem -Force.'
    }
  }
}

