function script:qs_goal_solution([string]$id) {
  switch -Exact ($id) {
    'notice' {
      return ,@('Get-Content notice.txt')
    }
    'search' {
      return ,@('Select-String "map-room" logs\*')
    }
    'who' {
      return ,@('Select-String 7714 staff.txt', 'Set-Content case-notes.txt "Otto Brandt"')
    }
    'count' {
      return ,@('Select-String 7714 logs\* | Measure-Object', 'Add-Content case-notes.txt 14')
    }
    'locker' {
      return ,@('Get-ChildItem lockers -Recurse -Filter "*otto*"', 'Set-Location lockers\basement\row-c\otto-brandt')
    }
    'map' {
      return ,@('Get-ChildItem -Force', 'Get-Content .false-bottom\star-map.txt')
    }
  }
}

function script:qs_finish_when {
  return [bool]((q_treasure 'starmap') -and (q_goal 'who') -and (q_goal 'count'))
}

function script:qs_finish_text {
  q_say 'Dr. Osei unrolls the Star Map on the long table and lets out a breath she''s been holding all day. Your case notes go to the police: a name and a count, straight from the logs.

You didn''t read a single log from top to bottom. You searched (Select-String), found (Get-ChildItem -Recurse), counted, sorted and joined tools with pipes. That''s how people handle thousands of lines every day.'
}

